fn main() {
    // Declare the app's own commands to Tauri's ACL. With an app manifest, every app command
    // needs an explicit `allow-<command>` grant in capabilities/, so a webview without a grant
    // (e.g. a future widgets webview) gets "not allowed by ACL". Without a manifest, Tauri
    // would skip the ACL check for app commands from any local webview.
    //
    // tauri-build writes the matching permission files to permissions/autogenerated/ on every
    // build (git-ignored: they are a pure function of this list).
    //
    // Test builds (`--features e2e`) add the isolation probe's canary, which only a runtime
    // capability for the main webview grants (src/e2e/mod.rs).
    const COMMANDS: &[&str] = &[
        "app_info",
        "report_first_paint",
        "widgets_policy",
        "widgets_show",
        "widgets_hide",
        "widgets_mount",
        "widgets_push",
        "widgets_register",
    ];
    const E2E_COMMANDS: &[&str] = &[
        "app_info",
        "report_first_paint",
        "widgets_policy",
        "widgets_show",
        "widgets_hide",
        "widgets_mount",
        "widgets_push",
        "widgets_register",
        "e2e_canary",
    ];
    let commands = if std::env::var_os("CARGO_FEATURE_E2E").is_some() {
        E2E_COMMANDS
    } else {
        COMMANDS
    };
    // The directory outlives a build, so drop files left by a build with another list (a test
    // build's e2e_canary must not reach a product build's ACL).
    if let Ok(entries) = std::fs::read_dir("permissions/autogenerated") {
        for entry in entries.flatten() {
            let path = entry.path();
            let stale = path
                .file_stem()
                .and_then(|stem| stem.to_str())
                .is_some_and(|stem| !commands.contains(&stem));
            if stale {
                let _ = std::fs::remove_file(path);
            }
        }
    }
    tauri_build::try_build(
        tauri_build::Attributes::new()
            .app_manifest(tauri_build::AppManifest::new().commands(commands)),
    )
    .expect("tauri-build failed");
}
